import rpy2.robjects as robjects
from rpy2.rinterface import RRuntimeError


def _inline_r_setup(code: str) -> str:
    """
    Configure R options based on the provided code snippet and return any necessary output or error messages.

    Args:
        code (str): The R code snippet to be executed.

    Returns:
        str: Any output or error messages generated during the execution of the code snippet.
    """
    try:
        # Initialize the R environment
        robjects.r('''
            options(warn=-1)
            options(stringsAsFactors = FALSE)
        ''')

        # Execute the provided code snippet
        result = robjects.r(code)

        # Handle different types of results
        if isinstance(result, robjects.Vector):
            # Convert vector to a space-separated string
            return ' '.join(map(str, result))
        elif isinstance(result, robjects.RObjectMixin):
            # Convert R object to string
            return str(result)
        else:
            # Fallback for other types
            return str(result)

    except RRuntimeError as e:
        # Handle R runtime errors and return the error message
        return str(e)


if __name__ == "__main__":
    test_code = "x <- c(1, 2, 3); mean(x)"
    print(_inline_r_setup(test_code))

