from typing import List

def files_list(path: str, include_hidden: bool = False) -> List[str]:
    """
    Lists all files in a given directory, including handling exceptions for non-existent paths and permission errors.

    Args:
        path (str): The directory path to list files from.
        include_hidden (bool): Whether to include hidden files (default: False).

    Returns:
        List[str]: A list of file names in the specified directory.

    Raises:
        FileNotFoundError: If the specified directory does not exist.
        PermissionError: If there are permission issues accessing the directory.
    """
    try:
        directory = Path(path)
        if not directory.exists():
            raise FileNotFoundError(f"The directory {path} does not exist.")
        if not directory.is_dir():
            raise ValueError(f"{path} is not a directory.")

        if include_hidden:
            return [file.name for file in directory.iterdir() if file.is_file()]
        else:
            return [file.name for file in directory.iterdir() if file.is_file() and not file.name.startswith('.')]
    except PermissionError as e:
        raise PermissionError(f"Permission denied when accessing {path}.") from e

def recursive_files_list(path: str, include_hidden: bool = False) -> List[str]:
    """
    Recursively lists all files in a given directory and its subdirectories.

    Args:
        path (str): The directory path to recursively list files from.
        include_hidden (bool): Whether to include hidden files (default: False).

    Returns:
        List[str]: A flattened list of file names in the specified directory and its subdirectories.
    """
    directory = Path(path)
    if not directory.exists():
        raise FileNotFoundError(f"The directory {path} does not exist.")
    if not directory.is_dir():
        raise ValueError(f"{path} is not a directory.")

    def _recursive_list(directory):
        """Helper function to recursively list files."""
        files = []
        for item in directory.iterdir():
            if item.is_file():
                if include_hidden or not item.name.startswith('.'):
                    files.append(item.name)
            elif item.is_dir():
                files.extend(_recursive_list(item))
        return files

    return _recursive_list(directory)

# Example usage
if __name__ == "__main__":
    try:
        print(files_list("/path/to/directory"))
        print(files_list("/path/to/directory", include_hidden=True))
        print(recursive_files_list("/path/to/directory"))
        print(recursive_files_list("/path/to/directory", include_hidden=True))
    except Exception as e:
        print(e)

