# Define a dictionary to store the associations between VCS names and methods
_vcs_handlers: Dict[str, Callable] = {}

def register_vcs_handler(vcs: str) -> Callable:
    """
    A decorator function that associates methods with specific version control systems (VCS).

    Args:
        vcs (str): The name of the VCS to associate with the method.

    Returns:
        Callable: The decorator function.
    """
    def decorator(method: Callable) -> Callable:
        _vcs_handlers[vcs] = method
        return method
    return decorator

# Example usage
@register_vcs_handler('git')
def handle_git():
    print("Handling Git operations")

@register_vcs_handler('hg')
def handle_hg():
    print("Handling Mercurial operations")

@register_vcs_handler('svn')
def handle_svn():
    print("Handling Subversion operations")

# Function to demonstrate retrieval of methods by VCS name
def get_vcs_handler(vcs: str) -> Callable:
    handler = _vcs_handlers.get(vcs)
    if handler:
        return handler
    else:
        raise ValueError(f"No handler registered for VCS '{vcs}'")

