from datetime import timedelta
from typing import Optional

def parse_frequency(frequency: str) -> Optional[timedelta]:
    """Parses a frequency string into a datetime.timedelta object.

    Args:
        frequency (str): A string representing a frequency, e.g., '3 days'.

    Returns:
        Optional[timedelta]: A timedelta object corresponding to the frequency,
                             or None if the frequency is 'None' or 'always'.

    Raises:
        ValueError: If the frequency string is invalid.
    """
    if frequency.lower() == 'none':
        return None
    elif frequency.lower() == 'always':
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError("Invalid frequency format.")

        amount = int(parts[0])
        unit = parts[1].lower()

        if unit == 'day' or unit == 'days':
            return timedelta(days=amount)
        elif unit == 'hour' or unit == 'hours':
            return timedelta(hours=amount)
        elif unit == 'minute' or unit == 'minutes':
            return timedelta(minutes=amount)
        elif unit == 'second' or unit == 'seconds':
            return timedelta(seconds=amount)
        else:
            raise ValueError(f"Unsupported time unit: {unit}")
    except ValueError as e:
        raise ValueError(f"Invalid frequency '{frequency}': {e}")
